const tabs=$$('[data-approach]');function activateApproach(b){const data=approaches[b.dataset.approach];tabs.forEach(t=>{t.setAttribute('aria-selected',t===b);t.tabIndex=t===b?0:-1});$('#approach-panel').setAttribute('aria-labelledby',b.id);$('#approach-label').textContent=data.label;$('#approach-title').textContent=data.title;$('#approach-description').textContent=data.description;$('#approach-steps').innerHTML=data.steps.map(s=>`<li>${s}</li>`).join('');$('.text-button').textContent=data.cta;if(!reduceMotion)$('#approach-panel').animate([{opacity:.3,transform:'translateY(7px)'},{opacity:1,transform:'translateY(0)'}],{duration:350,easing:'ease-out'})}
