const motionQuery=matchMedia('(prefers-reduced-motion:reduce)');let reduceMotion=motionQuery.matches,paused=reduceMotion;function setPaused(value){paused=value;document.body.classList.toggle('paused',paused);$('#motion-button').setAttribute('aria-pressed',paused);$('#motion-button span').textContent=paused?'Resume animations':'Pause animations';if(!paused&&!reduceMotion)startStars()}
$('#motion-button').addEventListener('click',()=>{if(reduceMotion){toast('Reduced motion is enabled in your device settings.');return}setPaused(!paused)});motionQuery.addEventListener('change',e=>{reduceMotion=e.matches;setPaused(reduceMotion)});
if('IntersectionObserver'in window){document.body.classList.add('motion-ready');const io=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');io.unobserve(e.target)}}),{threshold:.08});$$('.reveal').forEach(e=>io.observe(e));const counter=$('[data-count]');const countObserver=new IntersectionObserver(entries=>{if(!entries[0].isIntersecting)return;countObserver.disconnect();if(reduceMotion||paused)return;const start=performance.now();function tick(time){const f=Math.min((time-start)/1400,1);counter.textContent=Math.round(12000*(1-Math.pow(1-f,3))).toLocaleString('en-US');if(f<1)requestAnimationFrame(tick)}requestAnimationFrame(tick)},{threshold:.5});countObserver.observe(counter)}
let scrollTick=false;addEventListener('scroll',()=>{if(scrollTick)return;scrollTick=true;requestAnimationFrame(()=>{const height=document.documentElement.scrollHeight-innerHeight;$('.progress').style.width=(height?scrollY/height*100:0)+'%';scrollTick=false})},{passive:true});
