const canvas=$('#stars'),ctx=canvas.getContext('2d');let starFrame=0,points=[],cw=0,ch=0,lastDraw=0;function resizeStars(){cw=canvas.clientWidth;ch=canvas.clientHeight;const d=Math.min(devicePixelRatio||1,2);canvas.width=cw*d;canvas.height=ch*d;ctx?.setTransform(d,0,0,d,0,0);points=Array.from({length:Math.min(65,Math.floor(cw/17))},()=>({x:Math.random()*cw,y:Math.random()*ch,r:Math.random()*1.5+.4,v:Math.random()*.15+.06,phase:Math.random()*6.28}))}
